export type PracticeCategory =
  | 'Email & links'
  | 'Money & invoices'
  | 'Accounts & sign-ins'
  | 'Fake support'
  | 'Files & downloads'
  | 'Data & privacy'
  | 'Devices & networks'
  | 'Workplace security';

export type PracticeQuestion = {
  id: string;
  category: PracticeCategory;
  prompt: string;
  options: [string, string, string];
  safeOption: 0 | 1 | 2;
  lesson: string;
  warningSigns: string[];
};

// These are offline practice scenarios, not indicators about real messages or sites.
export const attackQuestionBank: PracticeQuestion[] = [
  { id: 'q001', category: 'Money & invoices', prompt: 'A regular supplier to your {org} emails new bank details and asks you to pay today, in confidence. What do you do?', options: ['Update the details and pay before the deadline.', 'Reply to the email asking the sender to confirm.', 'Pause payment and call the supplier using a number already on file.'], safeOption: 2, lesson: 'A familiar name does not prove who sent the message. Verify payment changes through a separate trusted contact route and follow your approval process.', warningSigns: ['New bank details', 'Urgency', 'Secrecy'] },
  { id: 'q002', category: 'Email & links', prompt: 'An email says your work password expires in 30 minutes and includes a sign-in button. What is safest?', options: ['Open the site or app you normally use by typing its address yourself.', 'Click the button because the message uses your organization’s logo.', 'Reply with your username and ask whether it is real.'], safeOption: 0, lesson: 'A logo and urgent deadline are easy to copy. Open the official service through a route you already trust, then check for alerts there.', warningSigns: ['Short deadline', 'Sign-in button', 'Threat of losing access'] },
  { id: 'q003', category: 'Email & links', prompt: 'You receive an invoice attachment you were not expecting. The sender asks you to enable editing to view it. What do you do?', options: ['Enable editing so the invoice is readable.', 'Verify with the sender using a known contact route before opening it.', 'Forward it to coworkers to see whether they can open it.'], safeOption: 1, lesson: 'Unexpected files can contain harmful content, and enabling editing can allow it to run. Confirm the file is expected through a separate trusted channel.', warningSigns: ['Unexpected attachment', 'Enable editing', 'Unusual request'] },
  { id: 'q004', category: 'Money & invoices', prompt: 'A message that appears to come from your manager asks you to buy gift cards and send the codes quickly. What is safest?', options: ['Buy one card first to check whether the request is genuine.', 'Ask the sender to confirm by replying to the same message.', 'Do not buy them; call your manager using a number you already have.'], safeOption: 2, lesson: 'Gift-card codes work like cash. Verify unusual payment requests outside the message and follow your organization’s approval process.', warningSigns: ['Gift-card codes', 'Urgency', 'Unusual payment method'] },
  { id: 'q005', category: 'Email & links', prompt: 'A cloud document arrives from an unfamiliar address and asks you to sign in to view it. What should you do?', options: ['Use the link because cloud documents are common at work.', 'Check with the supposed sender through a known contact route first.', 'Enter your work password, then change it if the page looks wrong.'], safeOption: 1, lesson: 'A fake document page can collect your password. Confirm the sender independently and use your usual cloud service rather than a sign-in link in an unexpected message.', warningSigns: ['Unknown sender', 'Unexpected document', 'Sign-in link'] },
  { id: 'q006', category: 'Email & links', prompt: 'A delivery text says a small fee is due and links to a page asking for your card details. What is safest?', options: ['Check the delivery in the carrier’s official app or website opened independently.', 'Pay the fee because the amount is small.', 'Reply with your tracking number and ask for a payment link.'], safeOption: 0, lesson: 'A small fee can be used to collect card details. Check delivery status through the carrier’s official app or address you enter yourself.', warningSigns: ['Unexpected fee', 'Text-message link', 'Card details requested'] },
  { id: 'q007', category: 'Email & links', prompt: 'A familiar contact sends a shortened link with no explanation. What should you do?', options: ['Open it because you recognize the contact name.', 'Ask what it is, using a separate trusted channel if the message feels unusual.', 'Paste it into a different browser to see what happens.'], safeOption: 1, lesson: 'A contact account can be misused, and a shortened address hides the destination. Confirm the message before opening an unexplained link.', warningSigns: ['Hidden destination', 'No context', 'Unexpected message'] },
  { id: 'q008', category: 'Email & links', prompt: 'A search result advertises your bank’s sign-in page, but the address looks slightly misspelled. What is safest?', options: ['Avoid it and open the bank using a saved bookmark or the address you know.', 'Continue if the page has the bank’s logo and colors.', 'Enter only your username to test whether the page is genuine.'], safeOption: 0, lesson: 'Lookalike sites can copy a real brand. Use a saved bookmark or type the official address yourself; do not enter information on a page with an unfamiliar address.', warningSigns: ['Misspelled address', 'Sponsored result', 'Login page'] },
  { id: 'q009', category: 'Email & links', prompt: 'An email says a shared mailbox is full and asks you to sign in to increase storage. What do you do?', options: ['Open the storage page from your usual email app or official account portal.', 'Click the email link because running out of storage is disruptive.', 'Send your password to the sender so they can raise the limit.'], safeOption: 0, lesson: 'Storage warnings can be copied to steal logins. Check storage from the service you already use, not through an unexpected email link.', warningSigns: ['Account warning', 'Sign-in link', 'Pressure to act'] },
  { id: 'q010', category: 'Email & links', prompt: 'A QR code on a poster promises a discount but the destination is hidden. What is safest?', options: ['Scan it and sign in if the page asks.', 'Use the organization’s official app or website to find the offer.', 'Scan it with a work phone because phones block unsafe pages.'], safeOption: 1, lesson: 'A QR code hides its web address until scanned. Check the offer through an official app or website instead of trusting the code alone.', warningSigns: ['Hidden web address', 'Unexpected offer', 'Login requested'] },
  { id: 'q011', category: 'Email & links', prompt: 'A password-reset email arrives, but you did not request one. What is safest?', options: ['Ignore the link, open the service yourself, and check account activity.', 'Click the reset link to see whether your account is affected.', 'Forward the email to a colleague and ask them to test the link.'], safeOption: 0, lesson: 'The email may be a lure or may signal someone is trying to access your account. Check through the official service and report repeated or unexpected requests.', warningSigns: ['Reset you did not request', 'Account access concern', 'Email link'] },
  { id: 'q012', category: 'Email & links', prompt: 'A message says you have a voicemail and includes an audio-file download from an unfamiliar sender. What do you do?', options: ['Download it because voice messages are usually harmless.', 'Verify with the supposed sender or your phone service through a known route.', 'Open it on a personal device instead of the work computer.'], safeOption: 1, lesson: 'Unexpected files can contain harmful content on any device. Confirm the voicemail through a trusted phone system or known contact before opening it.', warningSigns: ['Unexpected audio file', 'Unfamiliar sender', 'Download request'] },
  { id: 'q013', category: 'Email & links', prompt: 'A message from a coworker asks you to review a document, but the sender address differs by one letter. What is safest?', options: ['Open it because the display name is correct.', 'Check with your coworker through your usual work chat or phone.', 'Reply to the email and ask if they sent it.'], safeOption: 1, lesson: 'A small address difference can point to an impersonator. Confirm unexpected files using a separate communication channel you already trust.', warningSigns: ['Lookalike address', 'Unexpected file', 'Display name only'] },
  { id: 'q014', category: 'Email & links', prompt: 'A website opened from an email redirects to a different domain before asking you to sign in. What do you do?', options: ['Stop and close the page; open the service from a known address.', 'Continue if the first page looked familiar.', 'Use a different password so the real one stays protected.'], safeOption: 0, lesson: 'A change of destination can be part of a redirect trick. Do not sign in; reach the service independently and report the unusual message if it came from work.', warningSigns: ['Unexpected redirect', 'Different domain', 'Password request'] },
  { id: 'q015', category: 'Email & links', prompt: 'An email attachment is named “invoice.pdf.exe” and the sender says it must be opened today. What is safest?', options: ['Open it because the filename begins with PDF.', 'Do not open it; verify the invoice using a known supplier contact.', 'Rename it to “invoice.pdf” and try again.'], safeOption: 1, lesson: 'The final file extension determines what kind of file it is. An executable can run software, so do not open or rename it; confirm the invoice independently.', warningSigns: ['Executable extension', 'Urgency', 'Unexpected invoice'] },
  { id: 'q016', category: 'Email & links', prompt: 'A message says your account will be deleted unless you open a link and “verify now.” What do you do?', options: ['Open the official service yourself and check for a notice there.', 'Use the link because account deletion would be serious.', 'Reply with your account details to prevent deletion.'], safeOption: 0, lesson: 'Threats of account loss are often used to rush people. Check the service independently and ask your IT contact if the warning appears real.', warningSigns: ['Threat of deletion', 'Urgent link', 'Account details requested'] },
  { id: 'q017', category: 'Email & links', prompt: 'A supplier sends a file-sharing link after a meeting, but you were not told to expect it. What is safest?', options: ['Confirm with the supplier using contact details already on file.', 'Sign in with your work account to see what the file contains.', 'Download the file to your phone so it cannot affect the work computer.'], safeOption: 0, lesson: 'Unexpected links can lead to fake sign-in pages or unsafe files. Verify that the sender and file are expected before opening them.', warningSigns: ['Unexpected share', 'Sign-in prompt', 'No prior context'] },
  { id: 'q018', category: 'Email & links', prompt: 'A browser asks you to allow notifications so you can continue reading a news article. What is safest?', options: ['Allow it because the website requested it.', 'Choose Block or leave the prompt unanswered unless notifications are needed.', 'Allow it and share the prompt with coworkers.'], safeOption: 1, lesson: 'A site usually does not need notifications to display an article. Allow them only for a site you trust and genuinely want to hear from.', warningSigns: ['Unneeded permission', 'Unexpected prompt', 'Pressure to continue'] },
  { id: 'q019', category: 'Email & links', prompt: 'A CAPTCHA tells you to press a key combination and paste a command to prove you are human. What do you do?', options: ['Stop and close the page; do not paste or run the command.', 'Follow the steps because CAPTCHAs sometimes need extra checks.', 'Ask a coworker to run the command on their device first.'], safeOption: 0, lesson: 'A normal CAPTCHA should not ask you to run a computer command. Close the page and report it if it appeared during work.', warningSigns: ['Command to paste', 'Unusual key presses', 'Human check pretext'] },
  { id: 'q020', category: 'Email & links', prompt: 'A webpage asks you to install a “required viewer” before showing a document. What is safest?', options: ['Install it if the page uses your organization’s name.', 'Do not install it; verify the document through your usual work service.', 'Search for the same installer and use another download site.'], safeOption: 1, lesson: 'Unexpected viewers can install unwanted or harmful software. Use approved software sources and confirm the document through a trusted work channel.', warningSigns: ['Unexpected installer', 'Document blocked', 'Unverified download'] },

  { id: 'q021', category: 'Money & invoices', prompt: 'A message from the “director” asks you to buy gift cards and send the codes before a meeting. What is safest?', options: ['Buy the cards and send the codes to meet the deadline.', 'Verify the request by calling the director at a number you already know.', 'Ask the sender to confirm by replying “yes.”'], safeOption: 1, lesson: 'Gift-card codes are hard to recover once shared. Verify unusual money requests independently and use the organization’s normal approval process.', warningSigns: ['Gift cards', 'Urgent deadline', 'Executive impersonation'] },
  { id: 'q022', category: 'Money & invoices', prompt: 'A payroll email asks employees to submit new bank details through a link. What should you do?', options: ['Open the HR/payroll portal you normally use and ask HR whether a change is needed.', 'Use the email link because payroll must keep details current.', 'Send the details as a reply so HR can update them.'], safeOption: 0, lesson: 'Bank details are sensitive. Use the known payroll portal and verify unexpected changes with HR through its usual contact route.', warningSigns: ['Bank details', 'New link', 'Payroll pretext'] },
  { id: 'q023', category: 'Money & invoices', prompt: 'An invoice appears to be from a known supplier, but the amount is much larger than usual. What is safest?', options: ['Pay it to avoid late fees.', 'Check the order and confirm the invoice with the supplier using saved details.', 'Change the amount yourself and submit it.'], safeOption: 1, lesson: 'A mismatch between an invoice and the order should be resolved before payment. Verify through an established supplier contact and follow approval steps.', warningSigns: ['Unexpected amount', 'Payment pressure', 'Order mismatch'] },
  { id: 'q024', category: 'Money & invoices', prompt: 'A caller says they are from your bank and asks you to move funds to a “safe account.” What do you do?', options: ['End the call and call the bank using the number on your card or statement.', 'Transfer a small amount to test the account.', 'Give the caller your one-time code so they can stop the transfer.'], safeOption: 0, lesson: 'A bank will not need you to move money to an account supplied by an unexpected caller. Contact the bank using a trusted number and never share one-time codes.', warningSigns: ['Safe-account claim', 'Unexpected call', 'One-time code request'] },
  { id: 'q025', category: 'Money & invoices', prompt: 'A vendor asks you to pay an invoice to a different country than usual. What is safest?', options: ['Pause the payment and verify the change with a known vendor contact and an approver.', 'Pay it if the invoice number is correct.', 'Reply to the email and ask the sender to explain.'], safeOption: 0, lesson: 'Changes to payment destination need independent confirmation. Use known contact details and your organization’s approval process before sending money.', warningSigns: ['New country', 'Payment destination change', 'Email-only request'] },
  { id: 'q026', category: 'Money & invoices', prompt: 'A customer asks for a refund to a different card or account than the original payment. What should you do?', options: ['Follow the written refund process and ask a supervisor before changing the destination.', 'Send the refund quickly to keep the customer happy.', 'Use a personal payment app to finish the refund.'], safeOption: 0, lesson: 'Refunds to a different destination can redirect money. Follow the approved process and get a second check when the request is unusual.', warningSigns: ['Different destination', 'Urgent refund', 'Policy exception'] },
  { id: 'q027', category: 'Money & invoices', prompt: 'A caller claims to be a customer and asks you to read back their full card number from a receipt. What is safest?', options: ['Follow your payment-data policy and do not disclose card details; ask a supervisor if unsure.', 'Read it back after confirming their name.', 'Send a photo of the receipt to their phone.'], safeOption: 0, lesson: 'Names alone do not prove identity, and payment details should not be shared outside approved procedures. Ask a supervisor through a known route.', warningSigns: ['Sensitive card data', 'Unverified caller', 'Photo request'] },
  { id: 'q028', category: 'Money & invoices', prompt: 'A supplier emails a new bank account, and the message thread includes several old real invoices. What is safest?', options: ['Treat it as confirmed because the old thread is genuine.', 'Verify the account change with a saved phone number and a second approver.', 'Reply in the same thread to make sure the change is correct.'], safeOption: 1, lesson: 'An email thread can be compromised. Confirm payment changes outside the thread and follow a second-person approval for financial changes.', warningSigns: ['Bank change in thread', 'Old conversation reused', 'Payment risk'] },
  { id: 'q029', category: 'Money & invoices', prompt: 'A manager texts you from a new number asking you to urgently pay a vendor. What should you do?', options: ['Call the manager at the saved number and verify before paying.', 'Pay it because the text uses the manager’s name.', 'Ask the new number for a copy of their ID.'], safeOption: 0, lesson: 'Names and profile photos can be copied. Verify unexpected payment requests using a saved number and the usual approval process.', warningSigns: ['New number', 'Urgent payment', 'Impersonation'] },
  { id: 'q030', category: 'Money & invoices', prompt: 'A caller says a payment failed and asks you to read the verification code sent to your phone. What is safest?', options: ['Never read the code to a caller; contact your bank or payment provider directly.', 'Read the code if the caller knows the transaction amount.', 'Ask the caller to text their staff badge first.'], safeOption: 0, lesson: 'A verification code may authorize access or a payment. Keep it private and contact the provider using a number or app you already trust.', warningSigns: ['Verification code', 'Unexpected call', 'Payment pretext'] },
  { id: 'q031', category: 'Money & invoices', prompt: 'A vendor says a payment is overdue and threatens to stop service unless you pay using cryptocurrency. What do you do?', options: ['Pause and verify the invoice with the vendor through known contact details and an approver.', 'Pay a small amount in cryptocurrency first.', 'Use the payment address in the email to avoid service loss.'], safeOption: 0, lesson: 'A new payment method and pressure are reasons to pause. Verify the invoice independently and use only approved payment methods.', warningSigns: ['Cryptocurrency', 'Service threat', 'Urgent payment'] },
  { id: 'q032', category: 'Money & invoices', prompt: 'A coworker asks you to share your purchasing account because theirs is locked. What is safest?', options: ['Share your login just this once.', 'Ask them to use the account recovery process or contact the administrator.', 'Send them a screenshot with your password hidden.'], safeOption: 1, lesson: 'Shared accounts remove accountability and can expose funds. Use the approved recovery route and keep your password private.', warningSigns: ['Password sharing', 'Account lockout', 'Workaround request'] },
  { id: 'q033', category: 'Money & invoices', prompt: 'A payment request is within your spending limit, but the supplier details changed. What is safest?', options: ['Pay because the amount is authorized.', 'Verify the changed supplier details before paying, even if the amount is small.', 'Split the payment into two smaller transfers.'], safeOption: 1, lesson: 'A valid amount does not verify a changed destination. Confirm supplier details independently before sending any payment.', warningSigns: ['Changed account', 'Small payment used as test', 'Destination unverified'] },
  { id: 'q034', category: 'Money & invoices', prompt: 'A new supplier asks you to bypass purchase approval because the order is “only a formality.” What should you do?', options: ['Follow the normal purchasing and approval process.', 'Approve it to avoid delaying the team.', 'Ask the supplier to put the request in writing, then bypass approval.'], safeOption: 0, lesson: 'Approval steps protect the organization from errors and fraud. A supplier cannot authorize you to skip internal controls.', warningSigns: ['Bypass approval', 'External pressure', 'Unusual exception'] },
  { id: 'q035', category: 'Money & invoices', prompt: 'A caller claims a duplicate charge will be fixed if you install a payment app and share your screen. What is safest?', options: ['End the call and contact the merchant using its official number or app.', 'Install the app if the caller knows the charge amount.', 'Share your screen but hide the banking tab.'], safeOption: 0, lesson: 'Screen sharing can expose account details and give a caller influence over your actions. Contact the merchant through a trusted route instead.', warningSigns: ['Remote access', 'Payment problem pretext', 'Unsolicited caller'] },

  { id: 'q036', category: 'Accounts & sign-ins', prompt: 'A sign-in approval appears on your phone when you are not signing in. What do you do?', options: ['Approve it to make the notification go away.', 'Deny it and contact your trusted IT or account-support route.', 'Ask an unexpected caller whether the request is theirs.'], safeOption: 1, lesson: 'An unexpected approval may mean someone is trying to access your account. Deny it, do not share codes, and report it through a known support route.', warningSigns: ['Sign-in not started by you', 'Approval request', 'Possible password exposure'] },
  { id: 'q037', category: 'Accounts & sign-ins', prompt: 'A caller claiming to be IT asks you to read them the six-digit code sent to your phone. What is safest?', options: ['Share it if the caller knows your username.', 'Keep it private and call IT through your usual helpdesk contact.', 'Send the code in work chat instead of saying it aloud.'], safeOption: 1, lesson: 'One-time codes can let someone sign in as you. Real support should not need you to hand over a sign-in code.', warningSigns: ['Code request', 'Caller identity unverified', 'Sign-in access'] },
  { id: 'q038', category: 'Accounts & sign-ins', prompt: 'You receive several password-reset emails in a short time. You did not request them. What is safest?', options: ['Open the official account site yourself, check activity, and report the repeated alerts.', 'Use the newest email link and enter your current password.', 'Delete every alert so your inbox is clear.'], safeOption: 0, lesson: 'Repeated reset requests can be an attempt to access your account or pressure you into clicking. Check through the official service and tell IT if this is a work account.', warningSigns: ['Repeated reset requests', 'Unexpected sign-in activity', 'Possible account attack'] },
  { id: 'q039', category: 'Accounts & sign-ins', prompt: 'A work service asks you to set up multi-factor sign-in using a QR code sent by an unfamiliar caller. What do you do?', options: ['Do not scan it; contact IT through your normal helpdesk route.', 'Scan it so IT can finish setup remotely.', 'Send the caller a photo of the QR code for confirmation.'], safeOption: 0, lesson: 'A QR code can connect an attacker’s device to your account. Enroll only through the official setup flow you opened yourself or confirmed with IT.', warningSigns: ['Unexpected QR code', 'Caller-led setup', 'Account enrollment'] },
  { id: 'q040', category: 'Accounts & sign-ins', prompt: 'A coworker asks for your password because they need to finish a task while you are away. What is safest?', options: ['Share it through a private message and change it later.', 'Ask them to use their own account or request access through the administrator.', 'Write it on a note and leave it at their desk.'], safeOption: 1, lesson: 'Passwords should not be shared. Individual accounts keep activity traceable; access should be granted through the approved process.', warningSigns: ['Password request', 'Shared account', 'Convenience workaround'] },
  { id: 'q041', category: 'Accounts & sign-ins', prompt: 'A browser on a shared reception computer offers to save your work password. What should you choose?', options: ['Decline, sign out when finished, and follow the organization’s shared-device rules.', 'Save it so the next shift can work faster.', 'Save it if the browser profile has your first name.'], safeOption: 0, lesson: 'Other people may use a shared computer. Do not save your password there, and sign out of work services when you finish.', warningSigns: ['Shared computer', 'Password storage prompt', 'Multiple users'] },
  { id: 'q042', category: 'Accounts & sign-ins', prompt: 'A login page asks you to approve a new device you do not recognize. What is safest?', options: ['Deny the request and check account activity through the official service.', 'Approve it because the location may be approximate.', 'Approve it and change your password next week.'], safeOption: 0, lesson: 'Do not approve an unfamiliar device to clear a warning. Deny it and use the official account security page to review activity or contact IT.', warningSigns: ['Unknown device', 'Approval prompt', 'Delayed response suggested'] },
  { id: 'q043', category: 'Accounts & sign-ins', prompt: 'You think you entered your work password on a fake page. What is the best next step?', options: ['Tell trusted IT promptly and change the password from the official site using a clean route.', 'Wait to see whether anything happens.', 'Enter the password again on the same page to check.'], safeOption: 0, lesson: 'Quick reporting gives IT a chance to protect the account. Use the official site or a trusted device to change the password and follow IT’s instructions.', warningSigns: ['Password entered on unknown page', 'Account exposure', 'Need to report quickly'] },
  { id: 'q044', category: 'Accounts & sign-ins', prompt: 'A password manager warns that your work password appears in a reused-password list. What should you do?', options: ['Change it on the official work site to a unique password and tell IT if prompted.', 'Keep it because the work site has multi-factor sign-in.', 'Add a number to the old password and use it elsewhere.'], safeOption: 0, lesson: 'A password reused on another site can be tried against work accounts. Use a unique password and follow your organization’s sign-in policy.', warningSigns: ['Password reused', 'Exposure warning', 'Same credential elsewhere'] },
  { id: 'q045', category: 'Accounts & sign-ins', prompt: 'Your email settings show a forwarding address you did not add. What should you do?', options: ['Tell IT immediately and follow their steps to secure the account.', 'Delete it and assume the issue is fixed.', 'Wait until a message is forwarded before reporting it.'], safeOption: 0, lesson: 'An unknown forwarding rule can copy messages to someone else. IT should help secure the account and check for other unauthorized changes.', warningSigns: ['Unknown forwarding rule', 'Email privacy risk', 'Account settings changed'] },
  { id: 'q046', category: 'Accounts & sign-ins', prompt: 'A sign-in page opened from a work email has a web address you do not recognize. What is safest?', options: ['Close it and reach the work service using your usual bookmark or app.', 'Sign in because the page shows the company logo.', 'Enter a fake password to test whether it accepts it.'], safeOption: 0, lesson: 'Logos can be copied, and testing with a password still sends information to the page. Use the official route and report the message if suspicious.', warningSigns: ['Unknown web address', 'Copied logo', 'Sign-in request'] },
  { id: 'q047', category: 'Accounts & sign-ins', prompt: 'Your work phone with an authenticator app is missing. What should you do first?', options: ['Tell IT or your manager through another trusted device or phone as soon as possible.', 'Wait a few days in case it turns up.', 'Ask a coworker to approve sign-ins for you.'], safeOption: 0, lesson: 'The phone may be used to approve sign-ins. Report it promptly so the organization can protect access and help you recover your account.', warningSigns: ['Authenticator device missing', 'Sign-in approvals at risk', 'Recovery needed'] },
  { id: 'q048', category: 'Accounts & sign-ins', prompt: 'An account asks you to store backup codes. Where should they go?', options: ['Keep them in an approved secure place separate from the account password.', 'Post them in a team chat so others can help.', 'Save them in a public note on the shared computer.'], safeOption: 0, lesson: 'Backup codes can unlock an account. Store them only in an approved secure place and never share them in chat or on a shared device.', warningSigns: ['Account recovery codes', 'Shared storage', 'Credential exposure'] },
  { id: 'q049', category: 'Accounts & sign-ins', prompt: 'A new employee asks you to create one shared password for the whole team. What is safest?', options: ['Give each person an individual account with only the access they need.', 'Use one password and rotate it every month.', 'Write the shared password where the team can find it.'], safeOption: 0, lesson: 'Individual accounts make it easier to remove access and understand who did what. Ask an administrator to set up the right permissions.', warningSigns: ['Shared credential', 'No individual accountability', 'Broad access'] },
  { id: 'q050', category: 'Accounts & sign-ins', prompt: 'You receive a notice that a recovery phone number changed, but you did not change it. What do you do?', options: ['Open the official service from a known route, secure the account, and tell IT if it is a work account.', 'Ignore it unless you lose access.', 'Reply to the notice with your old phone number and password.'], safeOption: 0, lesson: 'An unknown recovery change may let someone take over the account. Check through the official service and report it promptly.', warningSigns: ['Recovery detail changed', 'You did not make the change', 'Account takeover risk'] },

  { id: 'q051', category: 'Fake support', prompt: 'A browser warning says your computer is infected and gives a phone number to call. What is safest?', options: ['Close the page and contact your usual IT support using saved details.', 'Call the number because the warning looks official.', 'Install the remote-access app listed on the page.'], safeOption: 0, lesson: 'A webpage can display a convincing warning and choose the number it wants you to call. Use your organization’s real support route instead.', warningSigns: ['Browser pop-up', 'Phone number supplied', 'Fear and urgency'] },
  { id: 'q052', category: 'Fake support', prompt: 'An unsolicited caller says they are IT and asks to control your computer remotely. What do you do?', options: ['End the call and contact IT using your normal helpdesk route.', 'Allow access if they know your name and job title.', 'Open remote access but do not show your email.'], safeOption: 0, lesson: 'Names and job details can be discovered. Remote access should happen only through a support request you initiated or verified with your organization.', warningSigns: ['Unsolicited call', 'Remote control request', 'Identity not verified'] },
  { id: 'q053', category: 'Fake support', prompt: 'A pop-up says you must install an update tool from an unfamiliar website to keep working. What is safest?', options: ['Close the prompt and ask IT or use the approved update method.', 'Install it because updates improve security.', 'Search for the same tool and download it from another site.'], safeOption: 0, lesson: 'Fake update tools can install unwanted software. Use the operating system’s built-in update page or your organization’s approved process.', warningSigns: ['Unfamiliar installer', 'Unexpected update', 'Work interruption threat'] },
  { id: 'q054', category: 'Fake support', prompt: 'A caller claiming to be a printer technician asks for your computer login to “fix the queue.” What should you do?', options: ['Do not share your password; verify the service request with your manager or IT.', 'Share it while they are on the phone, then change it later.', 'Write it down so they can enter it without hearing it.'], safeOption: 0, lesson: 'Support staff should not need your password. Verify the technician and the work order through your organization before allowing changes.', warningSigns: ['Password request', 'Unscheduled service', 'Technician identity unverified'] },
  { id: 'q055', category: 'Fake support', prompt: 'A caller says they need you to disable antivirus briefly to complete a repair. What is safest?', options: ['Decline and confirm the request with your trusted IT contact.', 'Turn it off for five minutes if they promise to turn it back on.', 'Ask them to email the instructions first.'], safeOption: 0, lesson: 'Disabling protection can leave the device exposed. Only your verified IT team should direct a change to security settings.', warningSigns: ['Disable protection', 'Caller-led change', 'Unexpected repair'] },
  { id: 'q056', category: 'Fake support', prompt: 'A person claiming to be a software vendor asks to share your screen to solve an account issue you did not report. What should you do?', options: ['End the request and contact the vendor or IT through a known route.', 'Share the screen but close your documents first.', 'Ask for their employee number and proceed if it sounds valid.'], safeOption: 0, lesson: 'Screen sharing can expose private messages, records, and account details. Start support through a trusted channel you choose.', warningSigns: ['Unrequested support', 'Screen-sharing request', 'Identity claim'] },
  { id: 'q057', category: 'Fake support', prompt: 'A caller says a delivery is waiting and asks you to read the code just sent to your phone. What is safest?', options: ['Keep the code private and contact the delivery company through its official app or number.', 'Read it if the caller knows your address.', 'Send the code in a text instead of saying it aloud.'], safeOption: 0, lesson: 'A one-time code may approve a sign-in or account change. Do not share it with a caller; check the delivery independently.', warningSigns: ['One-time code', 'Unexpected call', 'Delivery pretext'] },
  { id: 'q058', category: 'Fake support', prompt: 'A caller claiming to be from Microsoft says your computer has a virus and asks you to install a remote tool. What do you do?', options: ['End the call; contact your organization’s IT or the company through an official route.', 'Install the tool and watch what they do.', 'Give them access if they do not ask for payment.'], safeOption: 0, lesson: 'Unsolicited support calls can lead to remote control of your device. Do not install tools at a caller’s direction; use a trusted support route.', warningSigns: ['Unsolicited call', 'Remote tool', 'Virus claim'] },
  { id: 'q059', category: 'Fake support', prompt: 'A person at reception says they are here to fix the network but cannot show a work order. What should you do?', options: ['Keep them with you and verify the visit with the responsible manager or IT.', 'Let them into the equipment room to avoid delaying work.', 'Give them the network password so they can prove they are legitimate.'], safeOption: 0, lesson: 'A claimed service visit should be verified before access is granted. Use your organization’s visitor and maintenance process.', warningSigns: ['No work order', 'Restricted room access', 'Network credentials requested'] },
  { id: 'q060', category: 'Fake support', prompt: 'A support chat asks you to paste a command into a computer window to repair an error. What is safest?', options: ['Stop and ask your verified IT support to explain the command through the approved process.', 'Paste it because support chats are official.', 'Ask an online forum whether the command looks normal, then run it.'], safeOption: 0, lesson: 'Commands can change settings or run programs. Have verified IT review them before you execute anything you do not understand.', warningSigns: ['Command to paste', 'Unverified support', 'System changes'] },
  { id: 'q061', category: 'Fake support', prompt: 'An unexpected caller asks you to read your computer’s recovery key to unlock a file. What should you do?', options: ['Do not share it; contact IT through your usual channel immediately.', 'Read it if the caller knows the computer name.', 'Email it to the caller so they can verify it.'], safeOption: 0, lesson: 'A recovery key can unlock protected data. Keep it private and confirm any recovery request with trusted IT support.', warningSigns: ['Recovery key request', 'Unexpected caller', 'Sensitive access token'] },
  { id: 'q062', category: 'Fake support', prompt: 'A message from a supposed helpdesk asks you to install a browser extension to fix sign-in. What is safest?', options: ['Do not install it; verify the request with IT using the usual helpdesk route.', 'Install it if the extension has many positive reviews.', 'Install it in a personal browser instead.'], safeOption: 0, lesson: 'Extensions may read or change data on websites. Install only organization-approved extensions and confirm unexpected requests with IT.', warningSigns: ['Unexpected extension', 'Broad browser access', 'Sign-in problem pretext'] },
  { id: 'q063', category: 'Fake support', prompt: 'A caller says they need your approval to “cancel a hacker’s login.” A sign-in prompt appears on your phone. What do you do?', options: ['Deny it and contact IT through the saved helpdesk contact.', 'Approve it because the caller says it will cancel the login.', 'Read the approval number to the caller.'], safeOption: 0, lesson: 'Approving can authorize the attacker’s sign-in. Deny requests you did not start and report the caller through a trusted channel.', warningSigns: ['Unexpected approval', 'Caller controls the action', 'Account access at risk'] },
  { id: 'q064', category: 'Fake support', prompt: 'A fake support page asks for your work email password before showing a “security scan.” What is safest?', options: ['Close it and report the page; never enter your work password there.', 'Enter the password and check whether the scan finds anything.', 'Use your personal email password instead.'], safeOption: 0, lesson: 'A web page does not need your work password to scan your device. Use approved security tools and report unexpected credential requests.', warningSigns: ['Password for a scan', 'Unapproved page', 'Security pretext'] },
  { id: 'q065', category: 'Fake support', prompt: 'Someone asks you to install a certificate they emailed so a website will stop showing a warning. What do you do?', options: ['Do not install it; ask verified IT to check the warning and certificate.', 'Install it because certificates make websites secure.', 'Forward it to coworkers so they can test it.'], safeOption: 0, lesson: 'A certificate can affect which sites your device trusts. Install one only when verified IT explains and approves the change.', warningSigns: ['Unexpected certificate', 'Browser warning', 'Trust setting change'] },

  { id: 'q066', category: 'Files & downloads', prompt: 'A document says you must enable macros to view an invoice. You were not expecting it. What is safest?', options: ['Close it and verify the file with the sender through a known contact route.', 'Enable macros because the invoice is time-sensitive.', 'Upload it to a public file scanner using your work account.'], safeOption: 0, lesson: 'Macros can run actions on your computer. Do not enable them in an unexpected document; confirm the file and use only approved scanning tools.', warningSigns: ['Enable macros', 'Unexpected document', 'Urgency'] },
  { id: 'q067', category: 'Files & downloads', prompt: 'A compressed file contains another compressed file and came from an unknown sender. What should you do?', options: ['Do not open it; report it and verify whether it was expected.', 'Open each layer until you see a document.', 'Rename the file to .pdf to make it safe.'], safeOption: 0, lesson: 'Nested archives can hide executable or harmful files. Do not extract unexpected archives or change their names to bypass checks.', warningSigns: ['Nested archive', 'Unknown sender', 'Hidden file type'] },
  { id: 'q068', category: 'Files & downloads', prompt: 'A USB drive is left near the entrance and labeled “staff photos.” What is safest?', options: ['Give it to the responsible IT or security contact without plugging it in.', 'Plug it into a spare computer to see who owns it.', 'Take it home and scan it with a personal laptop.'], safeOption: 0, lesson: 'Unknown USB devices can carry harmful software. Leave it disconnected and report where you found it.', warningSigns: ['Unknown USB', 'Curiosity lure', 'Untrusted device'] },
  { id: 'q069', category: 'Files & downloads', prompt: 'Your computer blocks a downloaded file from an unfamiliar website. What should you do?', options: ['Leave it blocked and ask IT or use an approved download source.', 'Choose “keep anyway” because you need the file.', 'Download it again using a different browser.'], safeOption: 0, lesson: 'A browser warning is a useful stop signal. Get the file from an official source or ask IT to review it before opening.', warningSigns: ['Download blocked', 'Unfamiliar website', 'Warning bypass suggested'] },
  { id: 'q070', category: 'Files & downloads', prompt: 'A coworker sends a spreadsheet and asks you to enable content to reveal a hidden worksheet. What is safest?', options: ['Confirm they sent it and why content must be enabled before opening it.', 'Enable content because the sender is a coworker.', 'Forward it to your personal email and open it there.'], safeOption: 0, lesson: 'Spreadsheet content can run code. Confirm the file and purpose through a trusted channel, and follow your organization’s file-handling policy.', warningSigns: ['Enable content', 'Unexpected file', 'Workaround request'] },
  { id: 'q071', category: 'Files & downloads', prompt: 'An installer is offered through a pop-up ad while you are browsing. What should you do?', options: ['Close the ad and get software only from an approved store or official vendor site.', 'Install it if the ad says it is free.', 'Search for a mirror download if the button does not work.'], safeOption: 0, lesson: 'Ad links can lead to unwanted installers. Use approved software sources and ask IT before installing software on a work device.', warningSigns: ['Installer in an ad', 'Unknown publisher', 'Unapproved software'] },
  { id: 'q072', category: 'Files & downloads', prompt: 'A document download is password-protected, and the password arrives in the same email as the file. What is safest?', options: ['Verify the sender and file through a separate trusted route before opening it.', 'Open it because the password means it is secure.', 'Upload it to any free online converter to inspect it.'], safeOption: 0, lesson: 'A password can hide a file from some security checks. Verify unexpected attachments and use only approved tools to inspect work documents.', warningSigns: ['Password-protected file', 'Password in same message', 'Unexpected attachment'] },
  { id: 'q073', category: 'Files & downloads', prompt: 'A file named “schedule.pdf” appears as an application when you download it. What do you do?', options: ['Do not open it; check the full file type and report or verify the download.', 'Open it because the displayed name ends in PDF.', 'Rename it so it ends in .pdf and open it.'], safeOption: 0, lesson: 'The displayed name can hide the actual file type. Do not open a file that appears to be an application when you expected a document.', warningSigns: ['Name and type mismatch', 'Unexpected application', 'Download source unclear'] },
  { id: 'q074', category: 'Files & downloads', prompt: 'A browser asks to install an extension to view a PDF. What is safest?', options: ['Use the built-in PDF viewer or ask IT about an approved tool.', 'Install the extension if it has a PDF icon.', 'Install it only for this one document.'], safeOption: 0, lesson: 'An extension can access browser data. Use built-in or approved tools and avoid installing unexpected add-ons.', warningSigns: ['Unexpected extension', 'Document viewing pretext', 'Browser access'] },
  { id: 'q075', category: 'Files & downloads', prompt: 'A coworker asks you to download a “cleaner” app to speed up the shared computer. What should you do?', options: ['Ask IT or the device owner before installing anything.', 'Install it if it offers a free scan.', 'Use a personal account to install it without admin rights.'], safeOption: 0, lesson: 'Unapproved software can expose data or break protections. Have the device owner or IT review software before it is installed.', warningSigns: ['Unapproved app', 'Free scan claim', 'Shared device'] },
  { id: 'q076', category: 'Files & downloads', prompt: 'A file-sharing site asks you to disable your antivirus before downloading a form. What is safest?', options: ['Do not disable protection; find an official source or contact the sender.', 'Disable it briefly and turn it back on after downloading.', 'Use another computer with no antivirus.'], safeOption: 0, lesson: 'A legitimate form should not require disabling protection. Stop and verify the source through a trusted route.', warningSigns: ['Disable antivirus', 'Unofficial file site', 'Download pressure'] },
  { id: 'q077', category: 'Files & downloads', prompt: 'A work computer warns that an unknown app wants permission to make changes. What should you do?', options: ['Cancel and ask IT whether the app is approved.', 'Allow it if you were trying to open a document.', 'Click yes and see whether the document opens.'], safeOption: 0, lesson: 'Administrator permission can let an app change the device. Approve only software you expected and your organization has approved.', warningSigns: ['Unknown app', 'System-level permission', 'Unexpected prompt'] },
  { id: 'q078', category: 'Files & downloads', prompt: 'A coworker asks you to open a file on a shared USB drive, but you do not know who added it. What is safest?', options: ['Confirm its source and follow the organization’s process before opening it.', 'Open it because it is already inside the workplace.', 'Copy it to your phone to inspect it.'], safeOption: 0, lesson: 'Files on a shared device can come from outside the organization. Verify the source and scan using approved tools before opening.', warningSigns: ['Unknown file source', 'Shared removable drive', 'No verification'] },
  { id: 'q079', category: 'Files & downloads', prompt: 'A voice message attachment asks you to install a codec before it will play. What should you do?', options: ['Do not install the codec; verify the message and use an approved player.', 'Install it because audio files need codecs.', 'Search for a codec download and choose the first result.'], safeOption: 0, lesson: 'A fake codec can install unwanted software. Use approved software and verify unexpected attachments before opening them.', warningSigns: ['Unexpected codec', 'Attachment', 'Installer request'] },
  { id: 'q080', category: 'Files & downloads', prompt: 'An unknown person sends you a QR code that downloads a work app. What is safest?', options: ['Do not scan it; get the app from your approved store or IT.', 'Scan it if the message says the app is required.', 'Forward the QR code to a coworker to test.'], safeOption: 0, lesson: 'A QR code can hide a download destination. Install work apps only through approved sources and ask IT to confirm the request.', warningSigns: ['Hidden download link', 'Required-app claim', 'Unknown sender'] },

  { id: 'q081', category: 'Data & privacy', prompt: 'You are about to send a file containing {records} to an outside email address. What should you do?', options: ['Check the recipient and permission with your organization’s process before sending.', 'Send it because the address looks similar to the recipient’s name.', 'Use personal email if the work attachment is blocked.'], safeOption: 0, lesson: 'Sensitive records should go only to authorized recipients through approved channels. Double-check the address and ask your manager if unsure.', warningSigns: ['Sensitive records', 'External recipient', 'Address mismatch'] },
  { id: 'q082', category: 'Data & privacy', prompt: 'You accidentally email a document with private information to the wrong person. What is safest?', options: ['Tell your manager or privacy contact promptly and follow their response steps.', 'Delete the sent email and say nothing.', 'Ask the recipient to delete it, then assume the matter is closed.'], safeOption: 0, lesson: 'Prompt reporting helps the organization limit exposure and meet its response duties. Do not try to hide or handle the incident alone.', warningSigns: ['Wrong recipient', 'Private information', 'Incident response needed'] },
  { id: 'q083', category: 'Data & privacy', prompt: 'A colleague asks you to send work records to their personal email because the shared drive is slow. What do you do?', options: ['Use the approved work storage or ask IT for a safe way to share the file.', 'Send it to personal email and delete it later.', 'Compress it with a password and use a personal account.'], safeOption: 0, lesson: 'Personal email may not have the organization’s protections or retention controls. Use approved storage and sharing methods.', warningSigns: ['Personal email', 'Sensitive work file', 'Workaround'] },
  { id: 'q084', category: 'Data & privacy', prompt: 'A cloud-sharing dialog is set to “Anyone with the link.” The file contains internal information. What is safest?', options: ['Change access to named, authorized people and confirm the sharing policy.', 'Keep it public because the link is hard to guess.', 'Post the link only in a private social-media group.'], safeOption: 0, lesson: 'Anyone-with-link access can spread beyond the intended recipients. Restrict access to authorized people and follow your organization’s sharing rules.', warningSigns: ['Public link', 'Internal information', 'Uncontrolled sharing'] },
  { id: 'q085', category: 'Data & privacy', prompt: 'You need to discard a printed page with client or customer details. What should you do?', options: ['Use the approved confidential-paper bin or shredder.', 'Put it in the regular recycling bin face down.', 'Take a photo for your records, then throw it away.'], safeOption: 0, lesson: 'Printed information still needs protection. Use the organization’s secure disposal process for private records.', warningSigns: ['Personal data on paper', 'Unsecure bin', 'Physical exposure'] },
  { id: 'q086', category: 'Data & privacy', prompt: 'A coworker wants to photograph a screen containing {records} to ask for help in a public chat. What is safest?', options: ['Do not share the image; use an approved support channel and remove private details first.', 'Send it because the chat is convenient.', 'Cover names with a finger and take the photo.'], safeOption: 0, lesson: 'Screenshots can reveal more than the visible names, such as account details or other records. Use approved support channels and remove sensitive information.', warningSigns: ['Sensitive screen', 'Public chat', 'Screenshot sharing'] },
  { id: 'q087', category: 'Data & privacy', prompt: 'A form asks you to paste a customer list into a free online tool to format it. What should you do?', options: ['Use an approved tool or ask a manager before sharing customer data externally.', 'Paste the list because the tool says it deletes files.', 'Replace the names with initials and upload the rest.'], safeOption: 0, lesson: 'A free service may receive and store what you paste. Use tools approved for your organization’s data and ask before sending records outside.', warningSigns: ['External online tool', 'Customer data', 'Unverified privacy promise'] },
  { id: 'q088', category: 'Data & privacy', prompt: 'A document appears redacted with black rectangles over names. Can you forward it externally?', options: ['Check with the document owner; visual cover-ups may leave text underneath.', 'Forward it because the names are not visible.', 'Take a screenshot and send that instead.'], safeOption: 0, lesson: 'A black shape may cover text without removing it from the file. Use the approved redaction process and have the owner verify it before sharing.', warningSigns: ['Sensitive document', 'Visual-only redaction', 'External sharing'] },
  { id: 'q089', category: 'Data & privacy', prompt: 'A manager asks you to export a full contact list for a new service, but you do not know whether it is approved. What should you do?', options: ['Confirm the purpose, approval, and minimum data needed before exporting.', 'Export everything because the request came from a manager.', 'Send it to the vendor first and ask about approval later.'], safeOption: 0, lesson: 'Share only data the organization has approved for a clear purpose. Confirm what is needed and who is authorized to receive it.', warningSigns: ['Bulk export', 'External service', 'Approval unclear'] },
  { id: 'q090', category: 'Data & privacy', prompt: 'A work file synced to a personal cloud account by mistake. What is safest?', options: ['Tell IT or your manager promptly and follow their instructions to remove or secure the copy.', 'Delete the file and assume there is no remaining copy.', 'Keep using the personal account but add a password.'], safeOption: 0, lesson: 'A file may have synced to other devices or backups. Report it so the organization can assess and contain the exposure properly.', warningSigns: ['Personal cloud account', 'Work data copied', 'Unknown sync copies'] },

  { id: 'q091', category: 'Devices & networks', prompt: 'Public Wi-Fi asks you to sign in using your work email password. What is safest?', options: ['Do not enter the work password; use a trusted connection or ask IT about approved remote access.', 'Sign in if the Wi-Fi name matches the cafe.', 'Use your email password but change it after work.'], safeOption: 0, lesson: 'Public Wi-Fi names can be copied, and a hotspot should not need your work password. Use approved network access and follow remote-work guidance.', warningSigns: ['Work password requested', 'Public hotspot', 'Network identity uncertain'] },
  { id: 'q092', category: 'Devices & networks', prompt: 'Your browser shows a certificate or privacy warning on a work website. What should you do?', options: ['Stop and contact IT or the site owner through a trusted route.', 'Click through because the site is used every day.', 'Disable browser protection to open the page.'], safeOption: 0, lesson: 'The warning means the connection could not be verified as expected. Do not bypass it; ask IT to check whether the site or network has a problem.', warningSigns: ['Connection warning', 'Unverified site', 'Bypass request'] },
  { id: 'q093', category: 'Devices & networks', prompt: 'Windows says important security updates are ready. What is safest?', options: ['Install them through Windows Update or follow your organization’s approved update schedule.', 'Ignore them indefinitely to avoid a restart.', 'Use an update link from an email instead.'], safeOption: 0, lesson: 'Updates fix known weaknesses. Install them through the built-in settings or the process your organization provides, and restart when it is safe to do so.', warningSigns: ['Security update available', 'Untrusted update link', 'Long delay'] },
  { id: 'q094', category: 'Devices & networks', prompt: 'Windows Security says real-time protection is off, and you did not change it. What should you do?', options: ['Tell IT or check with the person responsible for the device before changing security settings.', 'Download a random antivirus tool from a search ad.', 'Turn off the firewall too so the settings match.'], safeOption: 0, lesson: 'Protection settings may be managed by another approved antivirus or by your organization. Verify the device’s protection status with IT before installing tools or changing settings.', warningSigns: ['Protection disabled', 'Unknown cause', 'Unapproved antivirus'] },
  { id: 'q095', category: 'Devices & networks', prompt: 'You see a sign-in alert from a location you do not recognize. What should you do?', options: ['Open the official account security page yourself, review activity, and report it if unexpected.', 'Click the alert email’s link and enter your password.', 'Ignore it unless someone complains.'], safeOption: 0, lesson: 'Check sign-in activity through the official service rather than a message link. If it was not you, tell IT and follow the account recovery steps.', warningSigns: ['Unknown location', 'Account alert', 'Message link'] },
  { id: 'q096', category: 'Devices & networks', prompt: 'A work laptop goes missing while you are away from the office. What should you do?', options: ['Contact your manager or IT immediately using another trusted device or phone.', 'Wait until you return in case it is at the office.', 'Post the laptop details and your account name publicly to ask for help.'], safeOption: 0, lesson: 'Prompt reporting lets IT protect accounts and respond to the missing device. Share the facts through the organization’s incident route.', warningSigns: ['Work device missing', 'Sensitive access stored', 'Fast reporting matters'] },
  { id: 'q097', category: 'Devices & networks', prompt: 'You need to charge your phone at a public USB port. What is safest?', options: ['Use your own wall charger or a trusted power-only battery pack.', 'Connect to any USB port and accept prompts to continue charging.', 'Borrow an unknown cable from a stranger.'], safeOption: 0, lesson: 'A USB connection can carry data as well as power. Your own wall charger or a trusted battery pack avoids connecting to an unknown device.', warningSigns: ['Unknown USB port', 'Unexpected data prompt', 'Untrusted cable'] },
  { id: 'q098', category: 'Devices & networks', prompt: 'A caller asks you to disable the office firewall because a website will not load. What should you do?', options: ['Keep the firewall on and ask IT to diagnose the site access problem.', 'Disable it until the site works.', 'Turn it off only for the caller’s laptop.'], safeOption: 0, lesson: 'A firewall helps block unwanted network connections. Let IT troubleshoot the site without removing protection.', warningSigns: ['Firewall change', 'Unverified caller', 'Security control bypass'] },
  { id: 'q099', category: 'Devices & networks', prompt: 'A backup drive has not been updated for months, and someone suggests plugging it into an unknown computer to test it. What is safest?', options: ['Ask IT or the device owner to test the backup using an approved device and process.', 'Plug it into any available computer.', 'Erase it and start a new backup without checking.'], safeOption: 0, lesson: 'Backups need to be both current and recoverable. Have the responsible person test them safely and confirm that important files can be restored.', warningSigns: ['Old backup', 'Unknown computer', 'Recovery not tested'] },
  { id: 'q100', category: 'Workplace security', prompt: 'Someone you do not recognize asks you to hold a secure door open because they forgot their badge. What should you do?', options: ['Ask them to use reception or the normal badge process; do not let them follow you in.', 'Hold the door because they seem familiar.', 'Photograph their badge and let them enter.'], safeOption: 0, lesson: 'A polite request does not verify access. Follow the visitor and badge process and contact reception or a manager if you are unsure.', warningSigns: ['Unrecognized visitor', 'Badge bypass', 'Tailgating request'] },
];
